<template><div class="page-shell"><header class="page-header"><p class="eyebrow">Teacher-assigned work</p><h1>Assignments</h1><p>Complete a check-in and review every answer when you finish.</p></header><p v-if="error" class="error-state">{{error}}</p><div v-if="!assignments.length&&!error" class="empty-state">No published assignments are waiting for you.</div><article v-for="item in assignments" :key="item.id" class="assignment glass-card"><header><div><span class="status">{{item.completed?'Completed':'Ready'}}</span><h2>{{item.title}}</h2><p>{{item.description}} · {{item.className}}</p></div><strong v-if="item.completed">{{item.score}} / {{item.total}}</strong></header><form v-if="!item.completed" @submit.prevent="submit(item)"><fieldset v-for="(q,index) in item.questions" :key="q.id"><legend>{{index+1}}. {{q.prompt}}</legend><label v-for="answer in q.answers" :key="answer"><input v-model="responses[item.id][q.id]" type="radio" :name="`${item.id}-${q.id}`" :value="answer"> {{answer}}</label></fieldset><button class="button primary">Submit assignment</button></form><div v-if="results[item.id]" class="result"><h3>{{results[item.id].score}} of {{results[item.id].total}} correct</h3><p v-for="f in results[item.id].feedback" :key="f.questionId">{{f.correct?'✓':'→'}} {{f.prompt}} — {{f.correctAnswer}}</p></div></article></div></template>
<script>import{api}from'../api';export default{name:'Assignments',data:()=>({assignments:[],responses:{},results:{},error:''}),async created(){document.title='Assignments · Math Practice';await this.load()},methods:{async load(){try{this.assignments=await api('/api/assignments/me');this.assignments.forEach(a=>this.responses[a.id]||={})}catch(e){this.error=e.message}},async submit(item){try{const answers=Object.entries(this.responses[item.id]).map(([questionId,answer])=>({questionId:Number(questionId),answer}));this.results[item.id]=await api(`/api/assignments/${item.id}/submit`,{method:'POST',body:JSON.stringify({answers})});await this.load()}catch(e){this.error=e.message}}}}</script>
<style scoped>.assignment{padding:1.5rem;margin-bottom:1.25rem}.assignment>header{display:flex;justify-content:space-between;gap:1rem}.assignment h2{font:700 1.8rem var(--ff-serif);margin:.65rem 0 .25rem}.assignment header p{color:hsl(var(--clr-white-600))}.assignment header>strong{font:800 2rem var(--ff-serif);color:hsl(var(--clr-accent-200))}form{display:grid;gap:1.5rem;margin-top:1.5rem}fieldset{border:1px solid hsl(var(--clr-white-200)/.12);border-radius:1rem;padding:1rem;display:grid;gap:.65rem}legend{font-weight:700;padding:0 .5rem}fieldset label{padding:.5rem;border-radius:.5rem;background:hsl(var(--clr-white-200)/.04)}form button{justify-self:start}.result{border-top:1px solid hsl(var(--clr-white-200)/.12);margin-top:1rem;padding-top:1rem}.result h3{color:hsl(var(--clr-accent-200))}</style>
